import {mentors,rankMentors} from './data.js';
import {createBookingStore,stages,rates,money,availability,dateLabel,koreaDate} from './booking-model.js';

export function createMatching(ui){
 const {app,icon,escape:e,header,footer,card,portrait}=ui;
 const store=createBookingStore();let diagnosis=null;let diagnosisSerial=0;let actor='learner';let findingTimer=null;let chosenSlot=null;let recommendationReady=false;
 const mentor=id=>mentors.find(m=>m.id===id);
 const route=()=>{const [path,q='']=(location.hash.slice(1)||'/').split('?');return {path,params:new URLSearchParams(q)};};
 function go(path){if(location.hash==='#'+path)ui.renderApp();else location.hash=path;}
 function snapshot(input){return {id:'diagnosis-'+(++diagnosisSerial),goal:input.goal,level:input.level,tools:input.tools||'',knowledge:input.knowledge||'',category:input.category,format:input.format,blocker:input.blocker||'',steps:[...(input.steps||[])],createdAt:new Date().toISOString()};}
 function finishDiagnosis(input){diagnosis=snapshot(input);recommendationReady=false;clearTimeout(findingTimer);}
 let draft=null;
function ensureDiagnosis(){const d=ui.getDiagnosis();if(!diagnosis&&d)diagnosis=snapshot(d);return diagnosis;}
 function diagnosisCard(d,expanded=false,editable=false){if(!editable)return `<details class="diagnosis-card" ${expanded?'open':''}><summary><span>${icon('book',19)} AI 활용 진단서</span><span>자동 첨부 ${icon('right',15)}</span></summary><div class="diagnosis-content"><div class="diagnosis-meta">${e(d.category)} · ${e(d.tools||d.level)}</div><dl><dt>이루고 싶은 목표</dt><dd>${e(d.goal)}</dd><dt>사전 지식</dt><dd>${e(d.knowledge||'—')}</dd><dt>원하는 수업 형식</dt><dd>${e(d.format||'미정')}</dd>${d.blocker?`<dt>추가로 남긴 내용</dt><dd>${e(d.blocker)}</dd>`:''}<dt>나에게 맞는 경로</dt><dd>${(d.steps||[]).map((s,i)=>`<span class="diagnosis-step">${i+1}. ${e(s)}</span>`).join('')}</dd></dl></div></details>`;return `<section class="diagnosis-card diagnosis-edit"><div class="diagnosis-edit-head"><span>${icon('book',19)} AI 활용 진단서</span><span class="edit-hint">${icon('check',14)} 직접 고칠 수 있어요</span></div><div class="diagnosis-content"><div class="diagnosis-meta">${e(d.category)}</div><label class="dx-field">이루고 싶은 목표<textarea data-dx="goal" rows="2" maxlength="600">${e(d.goal)}</textarea></label><label class="dx-field">지금 수준<select data-dx="level">${['처음 시작해요','도구를 써봤어요','직접 만들고 있어요'].map(v=>`<option ${d.level===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="dx-field">사전 지식<select data-dx="knowledge">${['아예 몰라요','용어만 들어봤어요','기본 개념은 알아요','실무에 적용해본 적 있어요'].map(v=>`<option ${d.knowledge===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="dx-field">원하는 수업 형식<input data-dx="format" maxlength="120" value="${e(d.format||'')}" placeholder="예: 온라인으로 주말에"></label><label class="dx-field">더 알려주실 내용 <small>(선택)</small><textarea data-dx="blocker" rows="2" maxlength="600" placeholder="지금 막혀 있는 부분이 있다면 적어주세요.">${e(d.blocker)}</textarea></label>${(d.steps||[]).length?`<div class="dx-static"><span>나에게 맞는 경로</span>${d.steps.map((s,i)=>`<span class="diagnosis-step">${i+1}. ${e(s)}</span>`).join('')}</div>`:''}<p class="dx-note">고친 내용 그대로 강사에게 전달됩니다.</p></div></section>`;}
 function progress(r){return `<ol class="match-progress" aria-label="매칭 진행 상태">${stages.map((s,i)=>`<li class="${i<r.status?'done':i===r.status?'current':''}" ${i===r.status?'aria-current="step"':''}><span>${i<r.status?icon('check',13):i+1}</span><b>${s}</b></li>`).join('')}</ol>`;}
 function finding(){ensureDiagnosis();if(!diagnosis)return emptyDiagnosis();if(recommendationReady){go('/recommendations');return '';}clearTimeout(findingTimer);findingTimer=setTimeout(()=>{recommendationReady=true;if(route().path==='/finding')go('/recommendations');},1700);return `${header()}<main id="main" class="matching-loading"><div class="finding-orbit">${icon('route',40)}</div><p class="section-kicker">FINDING YOUR AI TUTOR</p><h1>당신에게 꼭 맞는<br>AI 튜터를 찾고 있어요</h1><p>현재 수준과 목표를 바탕으로<br>함께할 사람 전문가를 추천해드릴게요.</p><div class="loading-facts"><span>${icon('check',16)} ${e(diagnosis.category)}</span><span>${icon('check',16)} ${e(diagnosis.level)}</span></div><div class="loading-track"><span></span></div><small>진단 기반 추천 화면을 준비하고 있어요.</small></main>${footer()}`;}
 function emptyDiagnosis(){return `${header()}<main id="main" class="not-found"><div class="chat-symbol">${icon('route',33)}</div><h1>먼저 나의 출발점을 알아볼까요?</h1><p>짧은 상담을 마치면 진단서와 맞춤 강사 추천이 준비돼요.</p><a href="#/chat" class="btn btn-dark">AI 상담 시작하기 ${icon('arrow',16)}</a></main>${footer()}`;}
 function recommendations(){ensureDiagnosis();if(!diagnosis)return emptyDiagnosis();recommendationReady=true;const top=rankMentors(diagnosis.category,diagnosis.level),ids=new Set(top.map(m=>m.id));const others=mentors.filter(m=>!ids.has(m.id));return `<div class="recommendation-page">${header('mentors')}<main id="main" class="container"><section class="recommendation-best"><div class="section-heading reco-head"><div><h2>나를 위한 추천 TOP 3</h2></div><div class="reco-aside"><p>당신에게 꼭 맞는 <em>AI 튜터</em>를 찾았어요</p><button class="text-button" data-match-diagnosis>내 진단서 보기 ${icon('right',14)}</button></div></div><div class="best-grid">${top.map((m,i)=>`<article class="best-item"><div class="rank-label"><b>0${i+1}</b><span>${i===0?'가장 먼저 만나보세요':'함께 비교해보세요'}</span></div>${card(m)}<div class="best-actions"><button class="btn btn-dark" data-match-chat="${m.id}">과외 신청하기</button><a class="btn btn-outline" href="#/mentor/${m.id}">정보 더보기</a></div></article>`).join('')}</div></section><section class="section other-mentors"><div class="section-heading"><div><h2>강사 풀 전체</h2><p>추천 밖의 강사도 직접 비교하고 선택할 수 있어요.</p></div><a href="#/mentors" class="text-link">전체 강사 ${icon('right',16)}</a></div><div class="pool-grid">${mentors.map(card).join('')}</div></section></main>${footer()}</div>`;}
 function ratePanel(m){return `<section class="rate-panel"><div class="rate-row"><span>온라인 1시간 기준</span><strong>${money(rates[m.id])}</strong></div><p class="rate-note">강사님이 보통 제안하는 금액이에요. 수업 시간과 범위에 따라 조율됩니다.</p><div class="free-chat">${icon('chat',18)}<div><strong>상담을 위한 채팅은 무료예요</strong><span>일정과 범위를 충분히 물어보고 결정하세요. 결제는 예약을 확정한 뒤에만 이뤄집니다.</span></div></div></section>`;}
function availabilityPanel(m){const slots=availability(m.id);return `<section class="availability-panel"><div class="availability-label">${icon('clock',18)} 상담 가능한 일정 <span>예시</span></div><p>한국시간 기준 · 최종 일정은 채팅에서 조율해요.</p><div class="availability-slots">${slots.map(s=>`<button data-profile-slot="${m.id}" data-date="${s.date}" data-time="${s.time}">${dateLabel(s.date,s.time)}</button>`).join('')}</div><div class="estimate-rate"><span>60분 기준 예시 금액</span><strong>${money(rates[m.id])}</strong></div></section>`;}
 function applyButton(m){return `<button class="btn btn-dark" data-match-apply="${m.id}">강사님 상담 신청 ${icon('arrow',16)}</button><small>진단서를 함께 첨부해 매칭을 신청해요.</small>`;}
 function scheduleFields(slot,includeDuration=true){return `<div class="form-grid"><label>날짜 <input name="date" type="date" min="${koreaDate()}" value="${e(slot.date)}" required></label><label>시작 시간 <input name="time" type="time" value="${e(slot.time)}" required></label></div>${includeDuration?`<label>수업 시간 <select name="duration">${[30,60,90,120,180].map(n=>`<option value="${n}" ${Number(slot.duration)===n?'selected':''}>${n}분</option>`).join('')}</select></label>`:''}<p class="field-hint">모든 일정은 한국시간(Asia/Seoul) 기준입니다.</p>`;}
 function application(id){const m=mentor(id);if(!m)return emptyDiagnosis();ensureDiagnosis();draft=diagnosis?null:{id:'draft-'+id,goal:'',level:'처음 시작해요',format:'',blocker:'',category:m.category,steps:[]};const d=diagnosis||draft;return `${header('mentors')}<main id="main" class="application-page"><a class="back-link light-back" href="#/mentor/${id}">${icon('left',16)} 강사 프로필로</a><div class="application-heading"><p class="section-kicker">LET'S MAKE IT HAPPEN</p><h1>첫 대화를 시작해볼까요?</h1><p>${draft?'아래 진단서를 채워 보내면, 강사가 첫 채팅부터 상황을 알고 시작해요.':'진단서를 함께 보내면, 내 상황을 처음부터 다시 설명하지 않아도 돼요.'}</p></div><div class="application-grid"><div><div class="application-mentor">${portrait(m,"mini-portrait")}<div><h2>${m.name} 강사</h2><p>${m.role} · ${m.category}</p></div></div>${draft?`<a class="draft-hint" href="#/chat?mentor=${id}">${icon('spark',18)}<div><strong>AI 상담을 먼저 하면 진단서가 자동으로 채워져요</strong><span>지금 직접 적으셔도 됩니다. 2분이면 끝나요.</span></div>${icon('right',16)}</a>`:''}${diagnosisCard(d,true,true)}<div class="application-guide">${icon('chat',22)}<div><strong>신청 후 1:1 채팅방이 열려요</strong><p>일정 조율 → 견적 확인 → 예약 확정 → 결제까지 한 대화에서 이어집니다.</p></div></div></div><form id="application-form" class="application-form" data-mentor="${id}"><div class="schedule-later">${icon('clock',18)}<div><strong>일정은 지금 정하지 않아도 돼요</strong><span>신청하면 1:1 채팅방이 열려요. 날짜와 시간은 강사님과 이야기하면서 정합니다.</span></div></div><label>강사에게 전하고 싶은 말 <span class="optional">선택</span><textarea name="note" maxlength="1200" rows="3" placeholder="예: 평일 저녁이 편해요. 보고서 자동화부터 해보고 싶어요."></textarea></label><label class="check-label"><input type="checkbox" name="consent" required><span>진단서를 첨부하여 상담을 신청합니다.</span></label><div class="form-error" role="alert"></div><button class="btn btn-dark" type="submit">진단서와 함께 매칭 신청 ${icon('arrow',17)}</button><small class="demo-boundary">체험 신청입니다. 실제 강사에게 전달되지 않으며 새로고침하면 내역이 초기화됩니다.</small></form></div></main>${footer()}`;}
 function roomList(activeId){return `<aside class="inbox-list"><div class="inbox-title"><h1>채팅·예약</h1><span>${store.list().length}</span></div>${store.list().length?store.list().map(r=>{const m=mentor(r.mentorId);return `<a class="inbox-contact ${r.id===activeId?'selected':''}" href="#/messages?request=${r.id}">${portrait(m,"mini-portrait")}<div><div class="inbox-contact-title"><b>${m.name}</b><span>${stages[r.status]}</span></div><p>${e(r.diagnosis.goal)}</p><small>${dateLabel(r.createdAt.slice(0,10))}</small></div></a>`;}).join(''):'<p class="empty-contacts">아직 시작한 대화가 없어요.</p>'}<a class="inbox-new" href="#/mentors">${icon('plus',17)} 다른 강사 만나보기</a></aside>`;}
 function quoteCard(r,q){const latest=r.quote?.id===q.id;const state=q.state;return `<article class="transaction-card"><div class="transaction-kicker">${icon('book',17)} 수업 견적서 <span>v${q.revision} · ${state==='superseded'?'이전 견적':state==='rejected'?'재조율 요청':state==='accepted'?'수락 완료':'확인 대기'}</span></div><h3>${e(r.diagnosis.category)} 1:1 맞춤 지도</h3><p class="quote-scope">${e(q.scope)}</p><dl class="transaction-dl"><div><dt>일정</dt><dd>${dateLabel(q.date,q.time)}</dd></div><div><dt>시간·방식</dt><dd>${q.duration}분 · ${e(q.mode)}</dd></div>${q.place?`<div><dt>장소</dt><dd>${e(q.place)}</dd></div>`:''}</dl><div class="quote-total"><span>최종 견적 금액</span><strong>${money(q.amount)}</strong></div>${latest&&state==='pending'&&actor==='learner'?`<button class="btn btn-dark" data-confirm-quote="${q.id}">견적 확인하고 예약 확정</button><button class="text-button" data-reject-quote="${q.id}">다시 조율하고 싶어요</button>`:state==='accepted'?'<div class="transaction-accepted">일정과 견적을 확인했어요</div>':''}<small>시연용 견적 · 표시 금액은 실제 청구되지 않습니다.</small></article>`;}
 function reservationCard(r){const b=r.reservation;return `<article class="transaction-card reservation-card"><div class="transaction-kicker">${icon('check',18)} 예약 확정</div><h3>${dateLabel(b.date,b.time)}</h3><p>${b.duration}분 · ${e(b.mode)}${b.place?' · '+e(b.place):''}</p><div class="quote-total"><span>결제 금액</span><strong>${money(b.amount)}</strong></div>${!r.payment&&actor==='learner'?`<button class="btn btn-dark" data-checkout>결제하기 ${icon('arrow',16)}</button>`:`<div class="transaction-accepted">${r.payment?'테스트 결제 완료':'사용자 결제 대기'}</div>`}<small>한국시간 기준 · 예약번호 ${e(b.id.toUpperCase())}</small></article>`;}
 function threadMessage(r,msg){if(msg.type==='system')return `<div class="thread-system">${e(msg.text)}</div>`;if(msg.type==='diagnosis')return `<div class="thread-attachment${msg.role?(msg.role===actor?' own':' other'):''}">${msg.role&&msg.role!==actor?`<div class="thread-author">${msg.role==='mentor'?mentor(r.mentorId).name+' 강사':'사용자'} <span>체험</span></div>`:''}${diagnosisCard(msg.diagnosis)}</div>`;if(msg.type==='quote'){const q=r.quotes.find(q=>q.id===msg.quoteId);return `<div class="thread-attachment">${quoteCard(r,q)}</div>`;}if(msg.type==='reservation')return `<div class="thread-attachment">${reservationCard(r)}</div>`;if(msg.type==='payment')return `<div class="thread-attachment"><div class="payment-receipt">${icon('check',23)}<div><strong>테스트 결제 완료 · ${money(r.payment.amount)}</strong><p>실제 결제 없이 흐름을 체험했어요.</p></div></div></div>`;if(msg.type==='schedule')return `<div class="thread-attachment"><article class="transaction-card schedule-card"><div class="transaction-kicker">${icon('clock',17)} ${msg.role==='mentor'?'강사':'사용자'}의 일정 제안</div><h3>${dateLabel(msg.slot.date,msg.slot.time)}</h3><p>${msg.slot.duration}분 · 한국시간</p>${actor==='mentor'&&!r.reservation?`<button class="btn btn-outline" data-slot-quote="${msg.id}">이 일정으로 견적 보내기</button>`:''}</article></div>`;const own=msg.role===actor;return `<div class="thread-text ${own?'own':'other'}">${!own?`<div class="thread-author">${msg.role==='mentor'?mentor(r.mentorId).name+' 강사':'사용자'} <span>체험</span></div>`:''}<div class="thread-bubble">${e(msg.text)}</div><time>${new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Seoul'}).format(new Date(msg.at))}</time></div>`;}
 function bookingPanel(r){const m=mentor(r.mentorId),b=r.reservation||r.quote;return `<aside class="booking-panel"><div class="booking-panel-title">${icon('book',18)} 신청 요약</div><a href="#/mentor/${m.id}" class="booking-mentor">${portrait(m,"mini-portrait")}<div><b>${m.name} 강사</b><small>${m.role}</small></div>${icon('right',14)}</a>${progress(r)}<div class="booking-summary"><span>나의 목표</span><p>${e(r.diagnosis.goal)}</p><span>${r.reservation?'확정 일정':b?'제안받은 일정':'일정'}</span><p>${(b||r.preferred)?`${dateLabel((b||r.preferred).date,(b||r.preferred).time)}<br>${(b||r.preferred).duration}분 · 한국시간`:'채팅에서 조율 예정'}</p><span>결제 상태</span><p>${r.payment?'테스트 결제 완료':r.reservation?'결제 대기':b?'견적 확인 대기':'견적 조율 전'}</p>${b?`<div class="booking-price"><strong>${money(b.amount)}</strong><small>예시 견적 금액</small></div>`:''}</div><div class="booking-panel-actions">${r.reservation?`<button class="btn btn-outline" data-booking-detail>예약 확인하기</button>${!r.payment&&actor==='learner'?'<button class="btn btn-dark" data-checkout>결제하기</button>':''}${r.payment&&r.status<3&&actor==='mentor'?'<button class="btn btn-dark" data-complete-demo>수업 완료 처리</button>':''}`:actor==='mentor'?`<button class="btn btn-dark" data-send-quote>견적서 보내기</button>`:(r.status===0?`<p class="panel-wait">${icon('clock',15)} 강사님이 수락하면 견적을 요청할 수 있어요.</p>`:`<button class="btn btn-dark" data-request-quote>견적 요청하기</button>`)}</div><p class="room-demo-note">체험 채팅방 · 실제 강사와 연결되지 않습니다. 금액은 예시이며 새로고침 시 내역이 초기화됩니다.</p></aside>`;}
 function inbox(id){const rows=store.list();const r=rows.find(r=>r.id===id)||(!id?rows[0]:null);if(!r)return `${header('messages')}<main id="main" class="inbox-shell empty-inbox">${roomList(null)}<div class="inbox-empty"><div class="chat-symbol">${icon('chat',30)}</div><h2>${id?'이 대화를 찾을 수 없어요':'강사와의 첫 대화를 시작해보세요'}</h2><p>매칭을 신청하면 진단서와 함께 채팅방이 열려요.<br>체험 내역은 페이지를 새로고침하면 초기화됩니다.</p><a class="btn btn-dark" href="${ensureDiagnosis()?'#/recommendations':'#/chat'}">${diagnosis?'추천 강사 만나보기':'상담하고 강사 추천받기'}</a></div></main>`;const m=mentor(r.mentorId);return `${header('messages')}<main id="main" class="inbox-shell" data-request-id="${r.id}">${roomList(r.id)}<section class="conversation"><header class="conversation-head"><a href="#/mentor/${m.id}">${portrait(m,"small-avatar")}<div><strong>${m.name} 강사</strong><small>${m.role}</small></div></a><span class="stage-chip">${stages[r.status]}</span></header><div class="role-switch-bar"><span>체험 화면</span><div class="role-switch" role="group" aria-label="체험 역할 전환"><button data-role="learner" class="${actor==='learner'?'selected':''}" aria-pressed="${actor==='learner'}">사용자</button><button data-role="mentor" class="${actor==='mentor'?'selected':''}" aria-pressed="${actor==='mentor'}">강사</button></div><small>${actor==='mentor'?'강사 역할로 메시지와 견적을 보낼 수 있어요':'강사 화면으로 전환해 답변과 견적을 보내보세요'}</small></div><div class="mobile-progress">${progress(r)}</div>${r.status===0&&actor==='mentor'?'<div class="acknowledge-banner">첨부된 진단서를 확인하고 신청을 수락해주세요. 수락하면 첫 인사가 자동으로 전달돼요.<button class="btn btn-dark" data-acknowledge>수락하고 인사 보내기</button></div>':''}<div class="conversation-thread" id="conversation-thread" role="log" aria-live="polite" aria-label="1대1 대화 내역"><div class="thread-system">${dateLabel(r.createdAt.slice(0,10))} · 새로운 대화의 시작</div>${r.messages.map(msg=>threadMessage(r,msg)).join('')}</div>${r.status===0&&actor==='learner'?`<div class="conversation-controls"><div class="await-accept">${icon('clock',20)}<div><strong>${mentor(r.mentorId).name} 강사님의 수락을 기다리고 있어요</strong><p>진단서를 보냈어요. 강사님이 수락하면 먼저 인사를 건네고, 그때부터 대화할 수 있어요.</p><small>체험 중이라면 위의 <b>강사</b> 버튼으로 역할을 바꿔 수락해볼 수 있어요.</small></div></div></div>`:`<div class="conversation-controls"><div class="conversation-tools">${!r.reservation?`<button data-open-schedule>${icon('clock',16)} 일정 제안</button>${actor==='mentor'?'<button data-send-quote>'+icon('book',16)+' 견적서 보내기</button>':'<button data-request-quote>'+icon('book',16)+' 견적 요청</button>'}`:`<button data-booking-detail>${icon('clock',16)} 예약 확인</button>${!r.payment&&actor==='learner'?'<button data-checkout>'+icon('check',16)+' 결제하기</button>':''}${r.payment&&r.status<3&&actor==='mentor'?'<button data-complete-demo>'+icon('check',16)+' 수업 완료</button>':''}`}</div><form id="direct-message-form" class="direct-message-form"><label class="sr-only" for="direct-message">1대1 메시지</label><textarea id="direct-message" name="message" rows="1" maxlength="1600" placeholder="${actor==='mentor'?'강사로서 답변을 입력해보세요':'강사님에게 궁금한 점을 물어보세요'}" required></textarea><button class="send-btn" type="submit" aria-label="메시지 보내기">${icon('up',20)}</button></form><div class="inline-error" role="alert"></div></div>`}</section>${bookingPanel(r)}</main>`;}
 function activeRequest(){const id=document.querySelector('[data-request-id]')?.dataset.requestId;return id?store.get(id):null;}
 function refreshRoom(scroll=false){const r=activeRequest();if(!r)return;app.innerHTML=inbox(r.id);bind();if(scroll)requestAnimationFrame(()=>{const el=document.getElementById('conversation-thread');if(el)el.scrollTop=el.scrollHeight;});}
 function errorMessage(error){const node=document.querySelector('.inline-error');if(node)node.textContent=error.message;}
 function modal(title,html,submit,buttonLabel='확인'){
  document.querySelector('#route-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='route-dialog';dialog.className='route-dialog';dialog.innerHTML=`<form id="route-dialog-form"><div class="dialog-heading"><h2 id="route-dialog-title">${title}</h2><button type="button" class="icon-btn" data-close-dialog aria-label="닫기">×</button></div><div class="dialog-content">${html}</div><div class="form-error" role="alert"></div>${submit?`<div class="dialog-actions"><button type="button" class="btn btn-outline" data-close-dialog>취소</button><button type="submit" class="btn btn-dark">${buttonLabel}</button></div>`:''}</form>`;dialog.setAttribute('aria-labelledby','route-dialog-title');document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('form').addEventListener('submit',ev=>{ev.preventDefault();if(!submit)return;try{submit(Object.fromEntries(new FormData(ev.target)));dialog.close();refreshRoom(true);}catch(err){dialog.querySelector('.form-error').textContent=err.message;}});dialog.showModal();}
 function quoteDialog(r,slot=null){const pref={...(slot||r.preferred||availability(r.mentorId)[0])};pref.duration=pref.duration||60;modal('견적서 보내기',`<p class="dialog-lead">일정과 수업 범위를 함께 제안해주세요. 사용자가 수락하면 예약이 확정됩니다.</p>${scheduleFields(pref)}<label>수업 범위<textarea name="scope" maxlength="1200" rows="3" required>${e(r.diagnosis.category+' 맞춤 지도 · '+r.diagnosis.goal)}</textarea></label><div class="form-grid"><label>진행 방식<select name="mode"><option>온라인 화상</option><option>오프라인</option></select></label><label>최종 견적 금액 (원)<input type="number" name="amount" min="1000" max="10000000" step="1" value="${Math.round(rates[r.mentorId]*pref.duration/60)}" required></label></div><label>장소 또는 접속 안내<input name="place" maxlength="200" placeholder="오프라인은 장소 필수 · 온라인 접속 링크는 추후 전달 가능"></label><p class="field-hint">입력한 금액은 이번 수업 전체의 최종 견적입니다. 체험용이며 실제 청구되지 않습니다.</p>`,input=>store.sendQuote(r.id,actor,input),'견적서 보내기');}
 function checkout(r){if(!r.reservation)throw new Error('예약을 먼저 확정해주세요.');const qid=r.quote.id;modal('예약 결제',`<div class="payment-demo-banner">테스트 결제 · 실제 청구 없음</div><div class="checkout-mentor"><b>${mentor(r.mentorId).name} 강사</b><p>${e(r.diagnosis.category)} 1:1 맞춤 지도</p></div><dl class="transaction-dl"><div><dt>일정</dt><dd>${dateLabel(r.reservation.date,r.reservation.time)}</dd></div><div><dt>수업 시간</dt><dd>${r.reservation.duration}분</dd></div><div><dt>진행 방식</dt><dd>${e(r.reservation.mode)}</dd></div></dl><div class="checkout-amount"><span>총 결제 금액</span><strong>${money(r.reservation.amount)}</strong></div><fieldset class="payment-methods"><legend>결제 수단</legend><label><input type="radio" name="method" value="카드" checked> 카드 결제</label><label><input type="radio" name="method" value="간편결제"> 간편결제</label></fieldset><label class="check-label"><input name="agree" type="checkbox" required><span>일정과 금액을 확인했으며 테스트 결제를 진행합니다.</span></label><p class="field-hint">카드 정보는 입력하지 않습니다. 실제 결제 기능은 결제사 연동 후 사용할 수 있습니다.</p>`,input=>{if(!input.agree)throw new Error('결제 내용을 확인해주세요.');store.pay(r.id,actor,qid,input.method);},money(r.reservation.amount)+' 테스트 결제');}
 function bind(){const form=document.getElementById('application-form');if(form)form.addEventListener('submit',ev=>{ev.preventDefault();try{const input=Object.fromEntries(new FormData(form));const edited={...(diagnosis||draft||{})};document.querySelectorAll('[data-dx]').forEach(el=>{edited[el.dataset.dx]=String(el.value||'').trim();});const r=store.create({...input,mentorId:form.dataset.mentor,diagnosis:edited,consent:input.consent==='on'});diagnosis=edited;actor='learner';go('/messages?request='+r.id);}catch(err){form.querySelector('.form-error').textContent=err.message;}});const dm=document.getElementById('direct-message-form');if(dm){dm.addEventListener('submit',ev=>{ev.preventDefault();try{const r=activeRequest();store.send(r.id,actor,new FormData(dm).get('message'));refreshRoom(true);}catch(err){errorMessage(err);}});dm.querySelector('textarea').addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();dm.requestSubmit();}});}}
 function renderRoute(path,params){let html;if(path==='/finding')html=finding();else if(path==='/recommendations')html=recommendations();else if(path.startsWith('/apply/'))html=application(path.split('/')[2]);else if(path==='/messages')html=inbox(params.get('request'));else return false;app.innerHTML=html;document.title=(path==='/messages'?'채팅·예약':path.startsWith('/apply/')?'매칭 신청':'나의 튜터 추천')+' · 먀칭';window.scrollTo(0,0);bind();if(path==='/messages')requestAnimationFrame(()=>{const el=document.getElementById('conversation-thread');if(el)el.scrollTop=el.scrollHeight;});return true;}
 document.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;try{
  if(b.hasAttribute('data-close-dialog')){document.querySelector('#route-dialog')?.close();return;}
  if(b.hasAttribute('data-match-diagnosis')){ensureDiagnosis();if(diagnosis)modal('나의 AI 활용 진단서',diagnosisCard(diagnosis,true));return;}
  if(b.hasAttribute('data-profile-slot')){chosenSlot={mentorId:b.dataset.profileSlot,date:b.dataset.date,time:b.dataset.time,duration:60};b.parentElement.querySelectorAll('button').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});return;}
  if(b.hasAttribute('data-match-chat')){ensureDiagnosis();if(!diagnosis){go('/chat');return;}const r=store.create({mentorId:b.dataset.matchChat,diagnosis,consent:true});actor='learner';go('/messages?request='+r.id);return;}
  if(b.hasAttribute('data-match-apply')){ensureDiagnosis();go('/apply/'+b.dataset.matchApply);return;}
  const r=activeRequest();if(!r)return;
  if(b.hasAttribute('data-role')){actor=b.dataset.role;refreshRoom();}
  else if(b.hasAttribute('data-acknowledge')){store.acknowledge(r.id,actor);refreshRoom(true);}
  else if(b.hasAttribute('data-request-quote')){store.requestQuote(r.id,actor);refreshRoom(true);}
  else if(b.hasAttribute('data-send-quote'))quoteDialog(r);
  else if(b.hasAttribute('data-slot-quote')){const msg=r.messages.find(m=>m.id===b.dataset.slotQuote);if(msg?.slot)quoteDialog(r,msg.slot);}
  else if(b.hasAttribute('data-open-schedule'))modal('일정 제안하기',`<p class="dialog-lead">가능한 날짜와 시간을 보내고, 채팅에서 함께 조율해요.</p>${scheduleFields(r.preferred||{...availability(r.mentorId)[0],duration:60})}`,input=>store.proposeSchedule(r.id,actor,input),'일정 보내기');
  else if(b.hasAttribute('data-confirm-quote')){const q=r.quote;modal('견적 확인 및 예약 확정',`<p class="dialog-lead">아래 내용을 수락하면 예약 상태가 ‘확정’으로 변경됩니다.</p><div class="confirmation-summary"><h3>${mentor(r.mentorId).name} 강사</h3><p>${dateLabel(q.date,q.time)} · ${q.duration}분</p><p>${e(q.mode)} ${e(q.place)}</p><strong>${money(q.amount)}</strong><p>${e(q.scope)}</p></div><p class="field-hint">예약 확정 후 이 채팅방에서 결제를 진행할 수 있어요.</p>`,()=>store.accept(r.id,actor,b.dataset.confirmQuote),'예약 확정하기');}
  else if(b.hasAttribute('data-reject-quote')){store.reject(r.id,actor,b.dataset.rejectQuote);refreshRoom(true);}
  else if(b.hasAttribute('data-checkout'))checkout(r);
  else if(b.hasAttribute('data-booking-detail'))modal('예약 확인',reservationCard(r)+(r.payment?`<div class="payment-demo-banner">${r.payment.method} · ${money(r.payment.amount)} 테스트 결제 완료</div>`:''));
  else if(b.hasAttribute('data-complete-demo'))modal('수업 완료 처리',`<p class="dialog-lead">예정된 수업이 끝난 상황을 가정하여 완료 상태를 체험합니다.</p><div class="confirmation-summary"><h3>${dateLabel(r.reservation.date,r.reservation.time)}</h3><p>${r.reservation.duration}분 · ${mentor(r.mentorId).name} 강사</p></div><p class="field-hint">실제 수업이 진행되었다는 확인이 아닌 UI 체험입니다.</p>`,()=>store.complete(r.id,actor,{simulate:true}),'완료 상태 체험하기');
 }catch(err){errorMessage(err);}});
 return {finishDiagnosis,renderRoute,availabilityPanel,ratePanel,applyButton,store,ensureDiagnosis,diagnosisCard,getDiagnosis:()=>diagnosis,setActor:v=>{actor=v;}};
}
